import java.util.*;

// Regenerate with: java Doubles.java > java_doubles.txt (JDK 19 or later).
// Prints "<IEEE-754 bits in hex> <Double.toString>" for edge cases, decoder-like values
// and random bit patterns (fixed seed), as golden data for the Go formatter.
public class Doubles {
    public static void main(String[] args) {
        List<Double> v = new ArrayList<>(List.of(0.0, -0.0, Double.MIN_VALUE, Double.MAX_VALUE, Double.MIN_NORMAL,
            1e7, 9999999.999999998, 1e-3, 0.0009999999999999998, 1e23, 2e23, 0.1 + 0.2, 87.0, 1.0E-5,
            (double) 0.1f, (double) 3.3f, (double) 12.14f, 5e-324, 1e-323, 4.4e-323, 9.5e-323, 1e22, 1e21));
        Random r = new Random(20261014);
        for (int i = 0; i < 10000; i++) {
            double d = Double.longBitsToDouble(r.nextLong());
            if (!Double.isNaN(d) && !Double.isInfinite(d)) v.add(d);
        }
        for (int i = 0; i < 5000; i++) v.add(Math.round(r.nextDouble() * 1e9) / Math.pow(10, r.nextInt(10))); // decoder-style decimals
        for (int i = 0; i < 3000; i++) v.add((double) Float.intBitsToFloat(r.nextInt())); // widened floats
        for (int i = 0; i < 2000; i++) v.add(r.nextDouble() * Math.pow(10, r.nextInt(40) - 20));
        StringBuilder out = new StringBuilder("# Generated by Java " + System.getProperty("java.version") + ": bits Double.toString\n");
        for (double d : v) {
            if (Double.isNaN(d) || Double.isInfinite(d)) continue;
            out.append(Long.toHexString(Double.doubleToRawLongBits(d))).append(' ').append(Double.toString(d)).append('\n');
        }
        System.out.print(out);
    }
}
